// 1. Get the raw response from the Facebook node
// We use '|| []' to safely handle cases where 'data' might be missing
const rawPosts = $input.first().json.data || [];

// 2. Map the Facebook fields to your Google Sheet headers
const cleanData = rawPosts.map(post => ({
  post_id: post.id,
  published_at: post.created_time,
  // Use '|| ""' to provide a default empty string if the field is missing
  caption: post.message || "", 
  media_url: post.full_picture || "", 
  permalink: post.permalink_url || "",
  platform: "Facebook"
}));

// 3. Return the cleaned list
return cleanData;

// 1. Get the raw Instagram data
const rawPosts = $input.first().json.data || [];

// 2. Map Instagram fields to Google Sheet headers
const cleanData = rawPosts.map(post => ({
  post_id: post.id,
  published_at: post.timestamp, // Instagram uses 'timestamp'
  caption: post.caption || "",
  media_url: post.media_url || "",
  permalink: post.permalink,
  platform: "Instagram"
}));

// 3. Return the cleaned list
return cleanData;

// 1. Get the list of posts (they are inside "elements")
const rawPosts = $input.first().json.elements || [];

// 2. Map LinkedIn data to your Google Sheet format
const cleanData = rawPosts.map(post => {
  // Convert timestamp (milliseconds) to readable Date
  const dateObj = new Date(post.publishedAt);

  // Create the Permalink
  // The ID looks like "urn:li:share:741...", we use the whole thing for the link
  const permalink = `https://www.linkedin.com/feed/update/${post.id}`;

  return {
    post_id: post.id,
    published_at: dateObj.toISOString(),
    caption: post.commentary || "",
    // Note: The new LinkedIn API gives a "Media URN" (ID) instead of a direct JPG link.
    // We will save this ID for now so the column isn't empty.
    media_url: post.content?.media?.id || "",
    permalink: permalink,
    platform: "LinkedIn"
  };
});

// 3. Return the cleaned list
return cleanData;

