// Loop through all incoming items
const results = $input.all().map(item => {
  // 1. Get the incoming date (from Facebook, Instagram, or LinkedIn)
  const rawDate = item.json.published_at;

  // 2. Create a Javascript Date Object
  // This automatically handles the "+0000" or ISO formats
  const dateObj = new Date(rawDate);

  // 3. Format for Strapi "Date" field (YYYY-MM-DD)
  // We split the ISO string at 'T' and take the first part
  const dateOnly = dateObj.toISOString().split('T')[0]; 

  // 4. Format for Strapi "DateTime" field (Full ISO)
  const dateTime = dateObj.toISOString();

  // 5. Return the item with these new specific fields attached
  return {
    json: {
      ...item.json, // Keep all original data
      strapi_date_final: dateOnly,      // Use this if your field is type "Date"
      strapi_datetime_final: dateTime   // Use this if your field is type "DateTime"
    }
  };
});

return results;

